// UsageTracker with Proxy
const trackedModel = new Proxy(model, {
  get: (target, prop) => {
    if (prop === "invoke") {
      return async (...args) => {
        const result = await target.invoke(...args);
        const lastAi = result.find(m => m._getType() === "ai");
        if (lastAi?.usage_metadata) {
          tracker.record(nodeName, lastAi.usage_metadata);
        }
        return result;
      };
    }
    return Reflect.get(target, prop);
  },
});
