// waitForA2ATools retry loop
let retries = 10;
let delay = 500;
while (retries > 0) {
  const status = await factory.getStatus();
  if (status.a2aReady) return status.a2aTools;
  await sleep(delay);
  delay = 100; // backoff to 100ms
  retries--;
}
console.warn("A2A tools not available");
```

