```typescript
// A2AToolGenerator error classification
function classifyError(error) {
  if (error.message.includes("ECONNREFUSED")) return "connection_refused";
  if (error.message.includes("timeout")) return "timeout";
  if (error.message.includes("404")) return "agent_not_found";
  if (error.message.match(/40[13]/)) return "authentication_error";
  return "unknown_error";
}
